sp_widget.css:
.tm-card{
    background:#fff;
    border-radius:18px;
    padding:20px;
    border:1px solid #e5e7eb;
    box-shadow:0 4px 16px rgba(0,0,0,.08);
}

.tm-card-head{
    margin-bottom:25px;
}

.tm-card-title{
    margin:0;
    font-size:18px;
    font-weight:600;
    color:#111827;
}

.tm-chart-container{
    display:flex;
    align-items:flex-end;
}

.tm-y-axis{
    width:60px;
    height:350px;
    display:flex;
    flex-direction:column;
    justify-content:space-between;
    font-size:12px;
    color:#64748b;
    margin-right:10px;
}

.tm-chart{
    flex:1;
    height:350px;
    display:flex;
    align-items:flex-end;
    justify-content:space-around;
    position:relative;
    border-left:1px solid #e5e7eb;
    border-bottom:1px solid #e5e7eb;
}

.tm-grid{
    position:absolute;
    left:0;
    right:0;
    height:1px;
    background:#f1f5f9;
}

.grid1{
    bottom:87px;
}

.grid2{
    bottom:175px;
}

.grid3{
    bottom:262px;
}

.grid4{
    bottom:349px;
}

.tm-bar-wrapper{
    position:relative;
    display:flex;
    flex-direction:column;
    align-items:center;
}

.tm-bar{
    width:50px;
    background:linear-gradient(
        180deg,
        #60A5FA,
        #2563EB
    );
    border-radius:10px 10px 0 0;
    transition:.3s;
    cursor:pointer;
}

.tm-bar:hover{
    transform:translateY(-5px);
    box-shadow:0 8px 20px rgba(37,99,235,.25);
}

.tm-label{
    margin-top:10px;
    font-size:12px;
    color:#64748B;
    font-weight:600;
}

.tm-tooltip{
    position:absolute;
    bottom:100%;
    margin-bottom:10px;
    background:#111827;
    color:#fff;
    font-size:12px;
    padding:6px 10px;
    border-radius:8px;
    opacity:0;
    visibility:hidden;
    transition:.2s;
    white-space:nowrap;
}

.tm-tooltip:after{
    content:'';
    position:absolute;
    top:100%;
    left:50%;
    transform:translateX(-50%);
    border:6px solid transparent;
    border-top-color:#111827;
}

.tm-bar-wrapper:hover .tm-tooltip{
    opacity:1;
    visibility:visible;
}

sp_widget.script:
(function() {

    data.chartHeight = 350;

    var days = {
        Mon: 0,
        Tue: 0,
        Wed: 0,
        Thu: 0,
        Fri: 0,
        Sat: 0,
        Sun: 0
    };

    var gr = new GlideRecord('x_snc_trackmed_medication_schedule_table');
    gr.query();

    while (gr.next()) {

        var scheduleDate = gr.getValue('start_date');

        if (!scheduleDate)
            continue;

        var gdt = new GlideDateTime(scheduleDate);
        var dayNumber = parseInt(gdt.getDayOfWeekLocalTime(), 10);

        switch(dayNumber) {

            case 1:
                days.Mon++;
                break;

            case 2:
                days.Tue++;
                break;

            case 3:
                days.Wed++;
                break;

            case 4:
                days.Thu++;
                break;

            case 5:
                days.Fri++;
                break;

            case 6:
                days.Sat++;
                break;

            case 7:
                days.Sun++;
                break;
        }
    }

    data.schedule = [
        {day:"Mon", value:days.Mon},
        {day:"Tue", value:days.Tue},
        {day:"Wed", value:days.Wed},
        {day:"Thu", value:days.Thu},
        {day:"Fri", value:days.Fri},
        {day:"Sat", value:days.Sat},
        {day:"Sun", value:days.Sun}
    ];

    var highest = Math.max(
        days.Mon,
        days.Tue,
        days.Wed,
        days.Thu,
        days.Fri,
        days.Sat,
        days.Sun
    );

    if (highest <= 10)
        data.maxValue = 10;
    else if (highest <= 50)
        data.maxValue = 50;
    else if (highest <= 100)
        data.maxValue = 100;
    else if (highest <= 200)
        data.maxValue = 200;
    else if (highest <= 500)
        data.maxValue = 500;
    else
        data.maxValue = Math.ceil(highest / 100) * 100;

    data.step4 = Math.round(data.maxValue * 0.75);
    data.step3 = Math.round(data.maxValue * 0.50);
    data.step2 = Math.round(data.maxValue * 0.25);

})();
